#include <WiFi.h>
#include <WebServer.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

// Smart Home Sensor Hub
// Shows temperature, humidity, and light level on an OLED and a local webpage.

const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";

const int DHT_PIN = 4;
const int LDR_PIN = 34;

DHT dht(DHT_PIN, DHT11);
Adafruit_SSD1306 display(128, 64, &Wire, -1);
WebServer server(80);

void setup() {
  dht.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);

  Serial.begin(115200);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }
  Serial.print("Dashboard: http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.begin();
}

void loop() {
  server.handleClient();
  updateDisplay();
  delay(1000);
}

void updateDisplay() {
  float tempC = dht.readTemperature();
  float humidity = dht.readHumidity();
  int lightLevel = analogRead(LDR_PIN);

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("Temp: "); display.print(tempC, 1); display.println(" C");
  display.print("Humidity: "); display.print(humidity, 0); display.println(" %");
  display.print("Light: "); display.println(lightLevel);
  display.display();
}

void handleRoot() {
  String page = "<h1>Home Sensor Hub</h1>";
  page += "<p>Temperature: " + String(dht.readTemperature(), 1) + " &deg;C</p>";
  page += "<p>Humidity: " + String(dht.readHumidity(), 0) + " %</p>";
  page += "<p>Light level: " + String(analogRead(LDR_PIN)) + "</p>";
  page += "<p><a href='/'>Refresh</a></p>";
  server.send(200, "text/html", page);
}
